import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createCustomerAddressesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createCustomerAddressesWorkflow(req.scope)
    .run({
      input: {
        addresses: [{
            customer_id: "cus_123",
            address_1: "456 Elm St",
            city: "Los Angeles",
            country_code: "us",
            postal_code: "90001",
            first_name: "Jane",
            last_name: "Smith",
          },
          {
            customer_id: "cus_321",
            address_1: "789 Oak St",
            city: "New York",
            country_code: "us",
            postal_code: "10001",
            first_name: "Alice",
            last_name: "Johnson",
          }
        ],
        additional_data: {
          crm_id: "123"
        }
      }
    })

  res.send(result)
}

